// @ts-strict-ignore
export type ICalendarLoaderIcons = {
  firstImage: string;
  secondImage: string;
  thirdImage: string;
};

type ISiteMetaDataLocale = {
  locale: string;
  default: boolean;
};

type ISiteMetaData = {
  title: string;
  author: string;
  description: string;
  siteUrl: string;
  locales: Array<ISiteMetaDataLocale>;
  timeZone: string;
  timeUtcOffsetSummerTime: string;
  timeUtcOffsetNormalTime: string;
  defaultLocale: string;
};

class SiteInfoHelper {
  calendarLoaderIcons: ICalendarLoaderIcons;
  siteMetaData: ISiteMetaData;

  constructor() {
    this.calendarLoaderIcons = null;
    this.siteMetaData = null;
  }

  setSiteMetaData(siteMetaData: ISiteMetaData): void {
    this.siteMetaData = siteMetaData;
  }

  getSiteMetaData(): ISiteMetaData | null {
    return this.siteMetaData;
  }

  setCalendarLoaderIcons(calendarLoaderIcons: ICalendarLoaderIcons): void {
    this.calendarLoaderIcons = calendarLoaderIcons;
  }

  getCalendarLoaderIcons(): ICalendarLoaderIcons | null {
    return this.calendarLoaderIcons;
  }
}

const helper = new SiteInfoHelper();
export default helper;
