import { useEffect, useMemo, useState } from "react";
import styles from "./separate-jetpass-booking.module.less";
import { createDate, DateHelper, isNonEmptyArray, insertIntoString, multipleClassNames } from "@/core/helpers";
import { addJetpassOrActivityCart } from "@/core/helpers/jetpass-helper";
import { onClickTimeSlot, TimeSlotList } from "@/core/components/modules/time-slot-list/time-slot-list";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import QuantitySelectorStyled from "@/core/components/primitives/quantity-selector-styled/quantity-selector-styled";
import { IGLKMyParksEntranceWithProductId } from "@/core/types/time-slots";
import { ProductCalendarService, TimeSlotService } from "@/core/services";
import dayjs from "dayjs";
import { motion, AnimatePresence } from "framer-motion";
import DialogModal, { DialogModalProps } from "@/core/components/primitives/dialog-modal/dialog-modal";
import { CurrencyHelper } from "@/core/helpers";
import { IGLKMyParksTimeSlot } from "@/core/types/time-slots";
import { SelectablePass } from "@/core/types/state/group-admission/group-admission-types";
import { ProductBlockFragment } from "@/core/types/purchase/product-types";
import AreaLoader from "@/core/components/primitives/area-loader/area-loader";
import RichText from "@/core/components/primitives/rich-text/rich-text";
import Calendar from "@/core/components/primitives/calendar/calendar";
import { useTranslation } from "react-i18next";
import useFocus from "@/core/hooks/use-focus";
import { DateSet } from "@/core/helpers/date-helper";
import { useShopServiceCartContext } from "@/core/contexts";
import { DateSlotItem } from "@parksandresorts/webapiproxy-types";
import structure from "@/core/styling/structure.module.less";
import { ExistingThemes } from "@/core/types";
import { useProductByContentfulId } from "@/core/hooks/product-hooks";

type SeparateJetpassBookingProps = {
  contentfulId: string;
  product: ProductBlockFragment;
  showOnlyToday?: boolean;
  labels?: Labels;
  componentTheme?: ExistingThemes;
  backgroundColor?: boolean;
};

type Labels = {
  heading: string;
  paragraph: any;
};

type CalendarSectionProps = {
  selectedDate: Date | null;
  selectedMonth: Date | null;
  isLoading: boolean;
  calendarData: Array<DateSlotItem> | null;
  setSelectedDate: (date: Date) => void;
  setSelectedMonth: (month: Date) => void;
};

type QuantitySectionProps = {
  price: number | null;
  isDisabled?: boolean;
  quantity: number;
  maxQuantity?: number;
  onChangeQuantity: (newQuantity: number) => void;
};

type TimeSlotSectionProps = {
  attraction: IGLKMyParksEntranceWithProductId | null;
  selectedTimeSlotId: number | null;
  quantity: number | null;
  onClickTimeSlot: onClickTimeSlot;
  isExpanded: boolean;
};

const SelectedDateSection = ({ error }: { error: string | null }) => {
  return (
    <div className={styles.selectedDateWrapper}>
      <h5 className={styles.selectedDateSubheading}>Till datum</h5>
      <h3 className={styles.date}>Idag, {DateHelper.toStringMMDDWeekday(createDate())}</h3>
      {error && <p>{error}</p>}
    </div>
  );
};

const CalendarSection = ({
  selectedDate,
  selectedMonth,
  calendarData,
  setSelectedDate,
  setSelectedMonth,
}: CalendarSectionProps) => {
  const today = createDate();
  const startDate = DateHelper.getModifiedDateByMonth(today, 0);
  const dates = useMemo(() => calendarData?.map(({ date }) => createDate(date)) ?? [], [calendarData]);
  const endDate = dates?.at(-1) ?? new Date();

  const days = new DateSet(dates);

  return (
    <>
      <h5>Välj ett datum</h5>
      <Calendar
        startDate={startDate}
        endDate={endDate}
        changedMonth={(month) => setSelectedMonth(month)}
        currentDisplayedMonth={selectedMonth ?? undefined}
        changeDate={(date) => {
          setSelectedDate(date);
        }}
        selectedDate={selectedDate ?? undefined}
        disabledDates={(d) => !days.has(d)}
      />
    </>
  );
};

const QuantitySection = ({ price, isDisabled, quantity, maxQuantity, onChangeQuantity }: QuantitySectionProps) => {
  const { t } = useTranslation();

  const subLabel =
    typeof price === "number" ? `${CurrencyHelper.formatToSek(price)} ${t("perPerson")}` : t("fetchingPrice");

  return (
    <div className={styles.quantityWrapper}>
      <QuantitySelectorStyled
        isDisabled={isDisabled}
        label={t("numberOfTickets")}
        sublabel={subLabel}
        quantity={quantity}
        maxQuantity={maxQuantity}
        onQuantityChange={onChangeQuantity}
      />
    </div>
  );
};

const TimeSlotSection = ({
  selectedTimeSlotId,
  attraction,
  quantity,
  onClickTimeSlot,
  isExpanded,
}: TimeSlotSectionProps) => {
  const { t } = useTranslation();

  return (
    <div className={styles.timeSlotsWrapper}>
      <motion.div
        className={styles.timeSlotInnerWrapper}
        initial={{ height: isExpanded || !attraction ? "auto" : 0, opacity: isExpanded || !attraction ? 1 : 0 }}
        animate={getAnimationForTimeSlots(isExpanded)}
      >
        {attraction ? (
          <>
            <TimeSlotList
              attractionName={attraction.attractionName}
              attractionId={attraction.attractionId}
              productId={attraction.productId}
              heading={t("upsellStepChooseATime")}
              quantity={quantity ?? undefined}
              selectedTimeSlotId={selectedTimeSlotId}
              timeSlots={
                attraction.timeSlots.map((slot) => ({
                  ...slot,
                  productId: attraction.productId,
                })) ?? []
              }
              showMoreThreshhold={12}
              onClick={onClickTimeSlot}
            />
            {!isNonEmptyArray(attraction.timeSlots) && (
              <p className={styles.timeSlotNoTimesLeft}>{t("noTimeSlotsForDay")}</p>
            )}
          </>
        ) : (
          <p className={styles.timeSlotNoTimesLeft}>{t("noTimeSlotsForDay")}</p>
        )}
      </motion.div>
    </div>
  );
};

const getAnimationForTimeSlots = (isExpanded: boolean) => {
  return isExpanded
    ? {
        height: "auto",
        opacity: 1,
        transition: {
          opacity: { delay: 0.05, duration: 0.3 },
          height: { duration: 0.2, type: "tween" },
        },
      }
    : {
        height: 0,
        opacity: 0,
        transition: {
          opacity: { duration: 0.2 },
          height: { duration: 0.2, type: "tween" },
        },
      };
};

const convertToSelectablePass = (
  timeSlot: IGLKMyParksTimeSlot,
  productId: number,
  attractionId: number,
  attractionName: string,
): SelectablePass => {
  const selectablePass: SelectablePass = {
    productId,
    attractionId: attractionId,
    attractionName: attractionName,
    timeSlotFrom: timeSlot.timeSlotFrom,
    timeSlotTo: timeSlot.timeSlotTo,
    timeSlotId: timeSlot.timeSlotId,
    quantity: timeSlot.quantity,
  };

  return selectablePass;
};

const getTimeSlotWithSameTime = (
  currenTimeSlot: SelectablePass,
  newTimeSlots: Array<IGLKMyParksTimeSlot>,
  selectedQuantity: number | null,
) => {
  const currentTimeSlotTime = dayjs(currenTimeSlot.timeSlotFrom).format("HH:mm");
  const timeSlotWithSameTime = newTimeSlots.find((timeslot) => {
    const isThereEnoughQuantity = timeslot.quantity >= (selectedQuantity ?? 0);
    const isTimeSlotOnSameTimeAsCurrent = dayjs(timeslot.timeSlotFrom).format("HH:mm") === currentTimeSlotTime;
    return isThereEnoughQuantity && isTimeSlotOnSameTimeAsCurrent;
  });

  return timeSlotWithSameTime ? timeSlotWithSameTime : null;
};

const SeparateJetpassBooking = ({
  contentfulId,
  product: productBlock,
  showOnlyToday,
  labels,
  componentTheme,
  backgroundColor,
}: SeparateJetpassBookingProps) => {
  const [calendarData, setCalendarData] = useState<Array<DateSlotItem> | null>(null);
  const [numberOfTickets, setNumberOfTickets] = useState<number>(0);
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [selectedMonth, setSelectedMonth] = useState<Date>(createDate());
  const [attractionForSelectedDate, setAttractionForSelectedDate] = useState<IGLKMyParksEntranceWithProductId | null>(
    null,
  );
  const [selectedTimeSlot, setSelectedTimeSlot] = useState<SelectablePass | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingTimeSlots, setIsLoadingTimeSlots] = useState(true);
  const [dialogModal, setDialogModal] = useState<Omit<DialogModalProps, "onCloseFunction"> | null>(null);
  const [isAddingToCart, setIsAddingToCart] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const { t } = useTranslation();

  const [focusRef, setFocus] = useFocus<HTMLDivElement>();

  const product = useProductByContentfulId(productBlock.contentful_id);
  if (!product?.glkProduct) throw new Error("Should have GLK product");

  const price = product.glkProduct.priceIncludingVat;
  const maxQuantity = product.glkProduct.maximumQuantity ?? 999;

  const attractionForSelectedDateWithFilteredTimeSlots = useMemo(() => {
    if (!attractionForSelectedDate) return null;

    const bookingLastActivityRelativeTime = product.glkProduct.metadata?.bookingLastActivityRelativeTime ?? 0;

    const filteredTimeSlots = attractionForSelectedDate.timeSlots.filter((slot) =>
      DateHelper.isBefore(DateHelper.addMinutes(createDate(), bookingLastActivityRelativeTime), slot.timeSlotFrom),
    );

    return {
      ...attractionForSelectedDate,
      timeSlots: filteredTimeSlots,
    };
  }, [attractionForSelectedDate, product]);

  const shopServiceCartContext = useShopServiceCartContext();

  useEffect(() => {
    ProductCalendarService.getProductsCalendar(product.productId)
      .then((response) => {
        const firstAvailableDate = isNonEmptyArray(response) ? createDate(response[0].date) : createDate();

        if (showOnlyToday) {
          const dateForToday = response.find((date) => DateHelper.isToday(date.date));

          if (dateForToday) {
            setSelectedDate(createDate(dateForToday.date));
          } else {
            setError(t("noJetpassForToday"));
            setIsLoadingTimeSlots(false);
          }
        }

        setCalendarData(response);
        setSelectedMonth(firstAvailableDate);
        setIsLoading(false);
      })
      .catch((error) => {
        setIsLoading(false);
        console.log(error);
      });
  }, []);

  useEffect(() => {
    if (!selectedDate) {
      return;
    }

    const dateAsString = dayjs(selectedDate).format("YYYY-MM-DD");

    TimeSlotService.getTimeSlotAttraction(product.productId, dateAsString)
      .then((timeSlotAttraction) => {
        const timeSlotsForSelectedDate = timeSlotAttraction?.timeSlots;

        setAttractionForSelectedDate(timeSlotAttraction);

        if (selectedTimeSlot) {
          const timeSlotWithSameTime =
            timeSlotsForSelectedDate &&
            getTimeSlotWithSameTime(selectedTimeSlot, timeSlotsForSelectedDate, numberOfTickets);

          if (timeSlotWithSameTime) {
            const selectablePass = convertToSelectablePass(
              timeSlotWithSameTime,
              timeSlotAttraction.productId,
              timeSlotAttraction.attractionId,
              timeSlotAttraction.attractionName,
            );
            setSelectedTimeSlot(selectablePass);
          } else {
            const oldTime = dayjs(selectedTimeSlot.timeSlotFrom).format("HH:mm");
            setSelectedTimeSlot(null);
            setDialogModal({
              headingText: t("noSpotsForTimeHeading"),
              bodyText: insertIntoString(t("noSpotsForTimeBody"), oldTime),
              primaryButtonText: t("okay"),
              primaryButtonAction: () => closeDialog(),
            });
          }
        }

        setIsLoadingTimeSlots(false);
      })
      .catch((error) => {
        console.error(error);
        setIsLoadingTimeSlots(false);
      });
  }, [selectedDate]);

  function closeDialog() {
    setFocus();
    setDialogModal(null);
  }

  const heading = labels?.heading ?? null;
  const richTextParagraph = labels?.paragraph ?? null;

  return (
    <section
      className={multipleClassNames(
        structure.block,
        structure.blockMaxWidthS,
        structure.blockFloatingPadding,
        styles.section,
        componentTheme,
      )}
      data-contentful-id={contentfulId}
    >
      <div ref={focusRef} tabIndex={-1} className={`${styles.wrapper}`} data-has-background-color={!!backgroundColor}>
        <AnimatePresence>
          {(isLoading || isLoadingTimeSlots) && showOnlyToday ? (
            <AreaLoader loaderText={t("loadingTimes")} />
          ) : (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ type: "tween", ease: "easeOut" }}
              className={styles.contentWrapper}
            >
              {heading && <h2 className={styles.heading}>{heading}</h2>}
              {richTextParagraph && (
                <>
                  <RichText richText={richTextParagraph} />
                </>
              )}
              {showOnlyToday ? (
                <SelectedDateSection error={error} />
              ) : (
                <CalendarSection
                  selectedDate={selectedDate}
                  selectedMonth={selectedMonth}
                  isLoading={isLoading}
                  calendarData={calendarData}
                  setSelectedDate={setSelectedDate}
                  setSelectedMonth={setSelectedMonth}
                />
              )}
              <QuantitySection
                price={price}
                isDisabled={selectedDate === null}
                quantity={numberOfTickets}
                maxQuantity={maxQuantity ?? selectedTimeSlot?.quantity ?? undefined}
                onChangeQuantity={(newQuantity: number) => setNumberOfTickets(newQuantity)}
              />
              <TimeSlotSection
                isExpanded={!!numberOfTickets}
                quantity={numberOfTickets}
                attraction={attractionForSelectedDateWithFilteredTimeSlots}
                selectedTimeSlotId={selectedTimeSlot ? selectedTimeSlot.timeSlotId : null}
                onClickTimeSlot={(timeSlot, productId, attractionId, attractionName) => {
                  const selectablePass = convertToSelectablePass(timeSlot, productId, attractionId, attractionName);
                  setSelectedTimeSlot(selectablePass);
                }}
              />
              <PrimaryButton
                isFullWidth={true}
                label={isAddingToCart ? t("addingToCart") : t("addToCart")}
                onClick={async () => {
                  if (!selectedDate || !calendarData) return;

                  try {
                    await addJetpassOrActivityCart(
                      t,
                      product,
                      numberOfTickets,
                      selectedTimeSlot,
                      selectedDate,
                      calendarData,
                      setIsAddingToCart,
                      shopServiceCartContext,
                    );
                    setNumberOfTickets(0);
                    setSelectedTimeSlot(null);
                    setSelectedDate(null);
                  } catch (error) {
                    console.error(error);
                  }
                }}
                isDisabled={!(selectedDate && selectedTimeSlot) || isAddingToCart}
              />
              {dialogModal && (
                <DialogModal
                  headingText={dialogModal.headingText}
                  bodyText={dialogModal.bodyText}
                  primaryButtonText={dialogModal.primaryButtonText}
                  primaryButtonAction={dialogModal.primaryButtonAction}
                  onCloseFunction={closeDialog}
                />
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </section>
  );
};

export default SeparateJetpassBooking;
